-- Generated by `make contracts` from contracts/census_fips_state.odcs.yaml. Do not edit: change the contract and regenerate.
-- Types the latest raw load only; every business rule lives in intermediate models.
with raw as (
    select * from {{ source('raw', 'census_fips_state') }}
),

latest as (
    select * from raw where filename = (select max(filename) from raw)
)

select
  "STATE" AS "postal",
  "STATEFP" AS "state_fips",
  "STATENS" AS "state_ns",
  "STATE_NAME" AS "state_name"
from latest
qualify row_number() over (partition by "state_fips" order by filename desc) = 1
